export default async function handler(req, res) {
  if (req.method !== 'GET' && req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }
  const authHeader = req.headers.authorization || '';
  const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  const supabaseUrl = process.env.SUPABASE_URL || 'https://swwvbfemxookbqoqotre.supabase.co';
  const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || 'sb_publishable_CZUC5ueCxjSDFeA3idgVZg_DaEoIJxf';
  try {
    const authRes = await fetch(`${supabaseUrl}/auth/v1/user`, {
      headers: {
        'Authorization': `Bearer ${token}`,
        'apikey': supabaseAnonKey
      }
    });
    if (!authRes.ok) {
      return res.status(401).json({ error: 'Invalid session' });
    }
    const authUser = await authRes.json();
    const email = (authUser && authUser.email ? authUser.email : '').trim().toLowerCase();
    if (email !== 'cesar.risso.f@gmail.com') {
      return res.status(403).json({ error: 'Forbidden' });
    }
    res.setHeader('Cache-Control', 'no-store');
    return res.status(200).json({ ok: true, data: FOUNDER_BACKUP });
  } catch (err) {
    return res.status(500).json({ error: 'Internal error' });
  }
}
